79	static CompressionMethod convertCompressionFromLibzip(libzippp_uint16 comp) {
80	    switch(comp) {
81	      case ZIP_CM_STORE:
82	          return CompressionMethod::STORE;
83	#ifdef ZIP_CM_BZIP2
84	      case ZIP_CM_BZIP2:
85	          return CompressionMethod::BZIP2;
86	#endif
87	      case ZIP_CM_DEFLATE:
88	          return CompressionMethod::DEFLATE;
89	#ifdef ZIP_CM_XZ
90	      case ZIP_CM_XZ:
91	          return CompressionMethod::XZ;
92	#endif
93	#ifdef ZIP_CM_ZSTD
94	      case ZIP_CM_ZSTD:
95	          return CompressionMethod::ZSTD;
96	#endif
97	      default:
98	          return CompressionMethod::DEFAULT;
99	    }
100	}
