260	bool ZipArchive::openBuffer(void** data, libzippp_uint32 size, OpenMode om, bool checkConsistency) {
261	    zip_error_t error;
262	    zip_error_init(&error);
263	
264	    /* create source from buffer */
265	    zip_source* localZipSource = zip_source_buffer_create(*data, size, 0, &error);
266	    if (localZipSource == nullptr) {
267	        Helper::callErrorHandlingCallback(&error, "can't create zip source: %s\n", errorHandlingCallback);
268	        zip_error_fini(&error);
269	        return false;
270	    }
271	
272	    bool open = openSource(localZipSource, om, checkConsistency);
273	    if (open) {
274	        if (om==Write || om==New) {
275	            bufferData = data;
276	            bufferLength = size;
277	
278	            //prevents libzip to delete the source when closing the ZipArchive
279	            zip_source_keep(localZipSource);
280	        }
281	    } else {
282	        zip_source_free(localZipSource);
283	        localZipSource = nullptr;
284	    }
285	    return open;
286	}
