288	bool ZipArchive::openSource(zip_source* source, OpenMode om, bool checkConsistency) {
289	    int zipFlag = 0;
290	    if (om == ReadOnly) { zipFlag = 0; }
291	    else if (om == Write) { zipFlag = ZIP_CREATE; }
292	    else if (om == New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
293	    else { return false; }
294	    if (checkConsistency) {
295	        zipFlag = zipFlag | ZIP_CHECKCONS;
296	    }
297	
298	    zip_error_t error;
299	    zip_error_init(&error);
300	
301	    /* open zip archive from source */
302	    zipHandle = zip_open_from_source(source, zipFlag, &error);
303	    if (zipHandle == nullptr) {
304	        Helper::callErrorHandlingCallback(&error, "can't open zip from source: %s\n", errorHandlingCallback);
305	        zip_error_fini(&error);
306	        return false;
307	    }
308	    zip_error_fini(&error);
309	
310	    zipSource = source;
311	
312	#ifdef LIBZIPPP_WITH_ENCRYPTION
313	    if (isEncrypted()) {
314	        int result = zip_set_default_password(zipHandle, password.c_str());
315	        if (result != 0) {
316	            close();
317	            return false;
318	        }
319	    }
320	#endif
321	
322	    mode = om;
323	    return true;
324	}
