326	bool ZipArchive::open(OpenMode om, bool checkConsistency) {
327	    if (isOpen()) { return om==mode; }
328	
329	    int zipFlag = 0;
330	    if (om==ReadOnly) { zipFlag = 0; }
331	    else if (om==Write) { zipFlag = ZIP_CREATE; }
332	    else if (om==New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
333	    else { return false; }
334	
335	    if (checkConsistency) {
336	        zipFlag = zipFlag | ZIP_CHECKCONS;
337	    }
338	
339	    int errorFlag = 0;
340	    zipHandle = zip_open(path.c_str(), zipFlag, &errorFlag);
341	
342	    //error during opening of the file
343	    if (errorFlag!=ZIP_ER_OK) {
344	        zip_error_t error;
345	        zip_error_init_with_code(&error, errorFlag);
346	        Helper::callErrorHandlingCallback(&error, "unable to open archive: %s\n", errorHandlingCallback);
347	        zip_error_fini(&error);
348	
349	        zipHandle = nullptr;
350	        return false;
351	    }
352	
353	    if (zipHandle!=nullptr) {
354	#ifdef LIBZIPPP_WITH_ENCRYPTION
355	        if (isEncrypted()) {
356	            int result = zip_set_default_password(zipHandle, password.c_str());
357	            if (result!=0) {
358	                close();
359	                return false;
360	            }
361	        }
362	#endif
363	
364	        mode = om;
365	        return true;
366	    }
367	
368	    return false;
369	}
