371	void progress_callback(zip* /*archive*/, double progression, void* ud) {
372	    ZipArchive* za = static_cast<ZipArchive*>(ud);
373	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
374	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
375	        ZipProgressListener* listener = *it;
376	        listener->progression(progression);
377	    }
378	}
