380	int progress_cancel_callback(zip* /*archive*/, void* ud) {
381	    ZipArchive* za = static_cast<ZipArchive*>(ud);
382	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
383	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
384	        ZipProgressListener* listener = *it;
385	        if (listener->cancel())
386	          return 1;
387	    }
388	    return 0;
389	}
