391	int ZipArchive::close(void) {
392	    if (isOpen()) {
393	
394	        //do not handle zipSource at all because it will be deleted by libzip
395	        //directly when not necessary anymore
396	
397	        if (!listeners.empty()) {
398	            zip_register_progress_callback_with_state(zipHandle, progressPrecision, progress_callback, nullptr, this);
399	            zip_register_cancel_callback_with_state(zipHandle, progress_cancel_callback, nullptr, this);
400	        }
401	
402	        //avoid to reset the progress when unzipping
403	        if (mode != ReadOnly) {
404	            progress_callback(zipHandle, 0, this); //enforce the first progression call to be zero
405	        }
406	
407	        int result = zip_close(zipHandle);
408	        if (result!=0) {
409	            Helper::callErrorHandlingCallback(zipHandle, "unable to close archive: %s\n", errorHandlingCallback);
410	            return LIBZIPPP_ERROR_HANDLE_FAILURE;
411	        }
412	
413	        zipHandle = nullptr;
414	        progress_callback(zipHandle, 1, this); //enforce the last progression call to be one
415	
416	        //push back the changes in the buffer
417	        int res_code = LIBZIPPP_OK;
418	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
419	            int srcOpen = zip_source_open(zipSource);
420	            if (srcOpen==0) {
421	                //IMPORTANT: the rewritten archive is read back into a *freshly allocated*
422	                //buffer. We must never read into nor realloc *bufferData here: that memory
423	                //is the storage backing the libzip source we are currently reading from.
424	                //Reusing it aliases the source and, depending on the libzip version (i.e.
425	                //whether it takes ownership of the buffer when writing), it makes
426	                //zip_source_free() release a buffer that realloc() already moved/freed,
427	                //which results in a double-free (see double_free_report / fromWritableBuffer).
428	                zip_int64_t increment = 1024;
429	                zip_int64_t capacity = bufferLength>0 ? static_cast<zip_int64_t>(bufferLength) : increment;
430	                char* outBuffer = static_cast<char*>(malloc(capacity * sizeof(char)));
431	                char* tempBuffer = outBuffer;
432	                zip_int64_t tempBufferSize = capacity;
433	                zip_int64_t totalRead = 0;
434	                zip_int64_t read = (outBuffer==nullptr) ? -1 : zip_source_read(zipSource, tempBuffer, tempBufferSize);
435	                while(read>0) {
436	                    totalRead += read;
437	                    if (totalRead>=capacity) {
438	                        zip_int64_t newCapacity = capacity + increment;
439	                        char* grownBuffer = static_cast<char*>(realloc(outBuffer, newCapacity * sizeof(char)));
440	                        if (grownBuffer==nullptr) {
441	                            Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: unable to extend buffer\n", errorHandlingCallback);
442	                            ::free(outBuffer);
443	                            outBuffer = nullptr;
444	                            read = -1;
445	                            break;
446	                        }
447	                        outBuffer = grownBuffer;
448	                        capacity = newCapacity;
449	                    }
450	                    tempBuffer = outBuffer+totalRead;
451	                    tempBufferSize = capacity-totalRead;
452	                    read = zip_source_read(zipSource, tempBuffer, tempBufferSize);
453	                }
454	
455	                zip_source_close(zipSource);
456	
457	                if (outBuffer!=nullptr && read>=0) {
458	                    //freeing zipSource first guarantees libzip has released whatever it owns
459	                    //before we touch *bufferData. With freep=0 (see openBuffer) libzip never
460	                    //frees *bufferData itself, so reclaiming it here is safe and leak-free.
461	                    zip_source_free(zipSource);
462	                    zipSource = nullptr;
463	
464	                    ::free(*bufferData);
465	                    *bufferData = outBuffer;
466	                    bufferLength = totalRead;
467	                } else {
468	                    Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
469	                    res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
470	                    if (outBuffer!=nullptr) { ::free(outBuffer); }
471	                    zip_source_free(zipSource);
472	                    zipSource = nullptr;
473	                }
474	            } else {
475	                Helper::callErrorHandlingCallback((zip*)nullptr, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
476	                res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
477	
478	                zip_source_free(zipSource);
479	                zipSource = nullptr;
480	            }
481	        }
482	
483	        mode = NotOpen;
484	        return res_code;
485	    }
486	
487	    return LIBZIPPP_OK;
488	}
