490	void ZipArchive::discard(void) {
491	    if (isOpen()) {
492	        zip_discard(zipHandle);
493	        zipHandle = nullptr;
494	
495	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
496	            zip_source_free(zipSource);
497	            zipSource = nullptr;
498	        }
499	
500	        mode = NotOpen;
501	    }
502	}
