510	string ZipArchive::getComment(State state) const {
511	    if (!isOpen()) { return string(); }
512	
513	    int flag = 0;
514	    if (state==Original) { flag = flag | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
515	    else { flag = flag | ZIP_FL_ENC_GUESS; }
516	
517	    int length = 0;
518	    const char* comment = zip_get_archive_comment(zipHandle, &length, flag);
519	    if (comment==nullptr) { return string(); }
520	    return string(comment, length);
521	}
