533	bool ZipArchive::setEntryCompressionConfig(ZipEntry& entry, CompressionMethod comp, libzippp_uint32 level) const {
534	    if (!isOpen()) { return false; }
535	    if (entry.zipFile!=this) { return false; }
536	    if (mode==ReadOnly) { return false; }
537	    const libzippp_uint16 comp_libzip = convertCompressionToLibzip(comp);
538	
539	    bool success = zip_set_file_compression(zipHandle, entry.index, comp_libzip, level)==0;
540	    if (success) {
541	        entry.compressionMethod = comp_libzip;
542	        entry.compressionLevel = level;
543	    }
544	    return success;
545	}
