554	ZipEntry ZipArchive::createEntry(struct zip_stat* stat) const {
555	    string name(stat->name);
556	    libzippp_uint64 index = stat->index;
557	    libzippp_uint64 size = stat->size;
558	    libzippp_uint16 compMethod;
559	    if (useArchiveCompressionMethod) {
560	        compMethod = this->compressionMethod;
561	    } else {
562	        compMethod = stat->comp_method;
563	    }
564	    libzippp_uint16 encMethod = stat->encryption_method;
565	    libzippp_uint64 sizeComp = stat->comp_size;
566	    int crc = stat->crc;
567	    time_t time = stat->mtime;
568	
569	    return ZipEntry(this, name, index, time, compMethod, compressionLevel, encMethod, size, sizeComp, crc);
570	}
