572	vector<ZipEntry> ZipArchive::getEntries(State state) const {
573	    if (!isOpen()) { return vector<ZipEntry>(); }
574	
575	    struct zip_stat stat;
576	    zip_stat_init(&stat);
577	
578	    vector<ZipEntry> entries;
579	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
580	    libzippp_int64 nbEntries = getNbEntries(state);
581	    for(libzippp_int64 i=0 ; i<nbEntries ; ++i) {
582	        int result = zip_stat_index(zipHandle, i, flag, &stat);
583	        if (result==0) {
584	            ZipEntry entry = createEntry(&stat);
585	            entries.push_back(entry);
586	        } else {
587	            //TODO handle read error => crash ?
588	        }
589	    }
590	    return entries;
591	}
