593	bool ZipArchive::hasEntry(const string& name, bool excludeDirectories, bool caseSensitive, State state) const {
594	    if (!isOpen()) { return false; }
595	
596	    int flags = 0;
597	    if (excludeDirectories) { flags = flags | ZIP_FL_NODIR; }
598	    if (!caseSensitive) { flags = flags | ZIP_FL_NOCASE; }
599	    if (state==Original) { flags = flags | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
600	    else { flags = flags | ZIP_FL_ENC_GUESS; }
601	
602	    libzippp_int64 index = zip_name_locate(zipHandle, name.c_str(), flags);
603	    return index>=0;
604	}
