661	void* ZipArchive::readEntry(const ZipEntry& zipEntry, bool asText, State state, libzippp_uint64 size) const {
662	    if (!isOpen()) { return nullptr; }
663	    if (zipEntry.zipFile!=this) { return nullptr; }
664	
665	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
666	    struct zip_file* zipFile = zip_fopen_index(zipHandle, zipEntry.getIndex(), flag);
667	    if (zipFile) {
668	        libzippp_uint64 maxSize = zipEntry.getSize();
669	        libzippp_uint64 uisize = size==0 || size>maxSize ? maxSize : size;
670	
671	        char* data = NEW_CHAR_ARRAY(uisize+(asText ? 1 : 0))
672	        if (!data) { //allocation error
673	            zip_fclose(zipFile);
674	            return nullptr;
675	        }
676	
677	        libzippp_int64 result = zip_fread(zipFile, data, uisize);
678	        zip_fclose(zipFile);
679	
680	        //avoid buffer copy
681	        if (asText) { data[uisize] = '\0'; }
682	
683	        libzippp_int64 isize = (libzippp_int64)uisize;
684	        if (result==isize) {
685	            return data;
686	        } else { //unexpected number of bytes read => crash ?
687	            delete[] data;
688	        }
689	    } else {
690	        //unable to read the entry => crash ?
691	    }
692	
693	    return nullptr;
694	}
