702	int ZipArchive::deleteEntry(const ZipEntry& entry) const {
703	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
704	    if (entry.zipFile!=this) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
705	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //deletion not allowed
706	
707	    if (entry.isFile()) {
708	        int result = zip_delete(zipHandle, entry.getIndex());
709	        if (result==0) { return 1; }
710	        return LIBZIPPP_ERROR_UNKNOWN; //unable to delete the entry
711	    } else {
712	        int counter = 0;
713	        vector<ZipEntry> allEntries = getEntries();
714	        vector<ZipEntry>::const_iterator eit;
715	        for(eit=allEntries.begin() ; eit!=allEntries.end() ; ++eit) {
716	            ZipEntry ze = *eit;
717	            string::size_type startPosition = ze.getName().find(entry.getName());
718	            if (startPosition==0) {
719	                int result = zip_delete(zipHandle, ze.getIndex());
720	                if (result==0) { ++counter; }
721	                else { return LIBZIPPP_ERROR_UNKNOWN; } //unable to remove the current entry
722	            }
723	        }
724	        return counter;
725	    }
726	}
