733	
734	int ZipArchive::renameEntry(const ZipEntry& entry, const string& newNameIn) const {
735	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
736	    if (entry.isNull() || entry.zipFile!=this) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
737	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //renaming not allowed
738	    if (newNameIn.length()==0) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
739	
740	    bool isDir = entry.isDirectory();
741	    string newName = newNameIn;
742	    if (isDir) {
743	        //a '/' is automatically appended to the destination of a directory
744	        if (!LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { newName += LIBZIPPP_ENTRY_PATH_SEPARATOR; }
745	    } else {
746	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { return LIBZIPPP_ERROR_INVALID_PARAMETER; } //a file cannot be renamed as a directory
747	    }
748	
749	    string sourceName = entry.getName();
750	    if (newName==sourceName) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
751	
752	    /*
753	     * Enumerate ALL the entries of the CURRENT state of the archive (i.e. including any
754	     * uncommitted addition/deletion/replacement/rename). Slots freed by zip_delete are
755	     * reported with a null name by libzip and simply skipped.
756	     */
757	    struct RenameItem {
758	        zip_uint64_t index;
759	        string oldName;
760	        string targetName;
761	    };
762	    vector<RenameItem> movedItems;
763	    vector<string> externalNames;
764	
765	    zip_int64_t nbSlots = zip_get_num_entries(zipHandle, 0);
766	    for(zip_int64_t i=0 ; i<nbSlots ; ++i) {
767	        const char* currentName = zip_get_name(zipHandle, (zip_uint64_t)i, ZIP_FL_ENC_GUESS);
768	        if (currentName==nullptr) { continue; } //entry deleted in the current (uncommitted) state
769	
770	        string name(currentName);
771	        bool participates = false;
772	        string targetName;
773	        if (isDir) {
774	            if (name==sourceName) {
775	                participates = true;
776	                targetName = newName;
777	            } else if (name.compare(0, sourceName.length(), sourceName)==0) {
778	                participates = true; //descendant of the moved directory
779	                targetName = newName + name.substr(sourceName.length());
780	            }
781	        } else {
782	            participates = (name==sourceName);
783	            targetName = newName;
784	        }
785	
786	        if (participates) {
787	            movedItems.push_back(RenameItem{(zip_uint64_t)i, name, targetName});
788	        } else {
789	            externalNames.push_back(name);
790	        }
791	    }
792	
793	    //the source entry itself must be part of the current archive
794	    bool sourceFound = false;
795	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
796	        if (it->oldName==sourceName) { sourceFound = true; break; }
797	    }
798	    if (!sourceFound) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
799	
800	    /*
801	     * Detect conflicts against the CURRENT state only: any entry that does not participate
802	     * in the move must not occupy the destination itself nor lie below it. Entries whose
803	     * parent directories are only implicit (no explicit directory entry in the archive) are
804	     * listed here as well, so a file such as new/target/last.txt prevents src/ from being
805	     * moved to new/target/ even when no new/ or new/target/ directory entry exists.
806	     */
807	    for(vector<string>::const_iterator it=externalNames.begin() ; it!=externalNames.end() ; ++it) {
808	        const string& external = *it;
809	        if (isDir) {
810	            if (external==newName || external.compare(0, newName.length(), newName)==0) {
811	                return LIBZIPPP_ERROR_UNKNOWN; //destination already occupied by an external entry: no overwrite, no merge
812	            }
813	        } else {
814	            if (external==newName) {
815	                return LIBZIPPP_ERROR_UNKNOWN; //the destination file already exists
816	            }
817	        }
818	    }
819	
820	    /*
821	     * Compute the (explicit) parent directories that will be missing once the entries have
822	     * been moved. A directory that is itself moved never has to be re-created here (it keeps
823	     * existing as an entry, only its name changes), even when a moved entry's new parent
824	     * chain goes through it.
825	     */
826	    vector<string> parentsToCreate;
827	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
828	        //for a directory target (ending with '/'), the first parent to consider is above the
829	        //target directory itself, hence the search starts at the penultimate separator
830	        string::size_type searchPos = it->targetName.length()-1;
831	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(it->targetName) && searchPos>0) { searchPos -= 1; }
832	        string::size_type slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, searchPos);
833	        while(slash!=string::npos && slash>0) {
834	            string parent = it->targetName.substr(0, slash+1);
835	
836	            //a moved destination already exists as an entry after the move
837	            bool isMovedDestination = false;
838	            for(vector<RenameItem>::const_iterator mit=movedItems.begin() ; mit!=movedItems.end() ; ++mit) {
839	                if (mit->targetName==parent) { isMovedDestination = true; break; }
840	            }
841	            if (isMovedDestination) { break; } //all the ancestors above are shared with this moved directory
842	
843	            //an external entry already provides the directory (explicitly)
844	            bool isExternal = false;
845	            for(vector<string>::const_iterator eit=externalNames.begin() ; eit!=externalNames.end() ; ++eit) {
846	                if (*eit==parent) { isExternal = true; break; }
847	            }
848	            if (isExternal) { break; } //the prefix chain up to this directory already exists
849	
850	            bool alreadyScheduled = false;
851	            for(vector<string>::const_iterator pit=parentsToCreate.begin() ; pit!=parentsToCreate.end() ; ++pit) {
852	                if (*pit==parent) { alreadyScheduled = true; break; }
853	            }
854	            if (!alreadyScheduled) { parentsToCreate.push_back(parent); }
855	            slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, slash-1);
856	        }
857	    }
858	    //create the parents from the shallowest to the deepest
859	    std::sort(parentsToCreate.begin(), parentsToCreate.end());
860	
861	    /*
862	     * Apply the rename deepest-first. This ordering is what makes moving a directory below
863	     * its own path possible (e.g. a/ to a/b/): the descendants free the names the ancestors
864	     * are renamed to, and the freshly re-created parent directories are not touched.
865	     */
866	    std::sort(movedItems.begin(), movedItems.end(),
867	              [](const RenameItem& a, const RenameItem& b) { return a.targetName > b.targetName; });
868	
869	    vector<zip_uint64_t> renamedIndices;
870	    vector<string> renamedOldNames;
871	    bool failure = false;
872	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
873	        int result = zip_file_rename(zipHandle, it->index, it->targetName.c_str(), ZIP_FL_ENC_GUESS);
874	        if (result!=0) { failure = true; break; }
875	        renamedIndices.push_back(it->index);
876	        renamedOldNames.push_back(it->oldName);
877	    }
878	
879	    //create the missing parent directories (e.g. re-create a/ when a/ moved to a/b/)
880	    vector<zip_uint64_t> createdDirIndices;
881	    if (!failure) {
882	        for(vector<string>::const_iterator it=parentsToCreate.begin() ; it!=parentsToCreate.end() ; ++it) {
883	            zip_int64_t dirIndex = zip_dir_add(zipHandle, it->c_str(), ZIP_FL_ENC_GUESS);
884	            if (dirIndex<0) { failure = true; break; }
885	            createdDirIndices.push_back((zip_uint64_t)dirIndex);
886	        }
887	    }
888	
889	    if (failure) {
890	        /*
891	         * The move could not be completed: undo everything done during THIS call so that the
892	         * archive is restored to its exact pre-call state. The directories created during
893	         * the move are removed first (they may occupy the original names), then the renames
894	         * are replayed in the reverse order (shallowest-first). Any other pending change is
895	         * left untouched.
896	         */
897	        for(vector<zip_uint64_t>::reverse_iterator dit=createdDirIndices.rbegin() ; dit!=createdDirIndices.rend() ; ++dit) {
898	            zip_delete(zipHandle, *dit);
899	        }
900	        for(zip_int64_t k=(zip_int64_t)renamedIndices.size()-1 ; k>=0 ; --k) {
901	            zip_file_rename(zipHandle, renamedIndices[(size_t)k], renamedOldNames[(size_t)k].c_str(), ZIP_FL_ENC_GUESS);
902	        }
903	        return LIBZIPPP_ERROR_UNKNOWN;
904	    }
905	
906	    return (int)movedItems.size();
907	}
