915	bool ZipArchive::addFile(const string& entryName, const string& file) const {
916	    if (!isOpen()) { return false; }
917	    if (mode==ReadOnly) { return false; } //adding not allowed
918	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
919	
920	    string::size_type lastSlash = entryName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR);
921	    if (lastSlash!=string::npos) { //creates the needed parent directories
922	        string dirEntry = entryName.substr(0, lastSlash+1);
923	        bool dadded = addEntry(dirEntry);
924	        if (!dadded) { return false; }
925	    }
926	
927	    const char* filepath = file.c_str();
928	    zip_source* source = zip_source_file(zipHandle, filepath, 0, -1);
929	    if (source!=nullptr) {
930	        libzippp_int64 result = zip_file_add(zipHandle, entryName.c_str(), source, ZIP_FL_OVERWRITE);
931	        if (result>=0) {
932	            zip_file_set_mtime(zipHandle, result, time(nullptr), 0);
933	            if (useArchiveCompressionMethod) {
934	              zip_set_file_compression(zipHandle, result, compressionMethod, 0);
935	            }
936	#ifdef LIBZIPPP_WITH_ENCRYPTION
937	            if (isEncrypted()) {
938	                if (zip_file_set_encryption(zipHandle,result,encryptionMethod,nullptr)!=0) { //unable to encrypt
939	                    zip_source_free(source);
940	                } else {
941	                    return true;
942	                }
943	            } else {
944	                return true;
945	            }
946	#else
947	            return true;
948	#endif
949	        } else {
950	            //unable to add the file
951	            zip_source_free(source);
952	        }
953	    } else {
954	        //unable to create the zip_source
955	    }
956	    return false;
957	}
