1049	
1050	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::function<bool(const void*,libzippp_uint64)> writeFunc, State state, libzippp_uint64 chunksize) const {
1051	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1052	    if (zipEntry.zipFile!=this) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1053	
1054	    int iRes = LIBZIPPP_OK;
1055	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
1056	    struct zip_file* zipFile = zip_fopen_index(zipHandle, zipEntry.getIndex(), flag);
1057	    if (zipFile) {
1058	        libzippp_uint64 maxSize = zipEntry.getSize();
1059	        if (!chunksize) { chunksize = LIBZIPPP_DEFAULT_CHUNK_SIZE; } // use the default chunk size (512K) if not specified by the user
1060	
1061	        if (maxSize<chunksize) {
1062	            char* data = NEW_CHAR_ARRAY(maxSize)
1063	            if (data!=nullptr) {
1064	                libzippp_int64 result = zip_fread(zipFile, data, maxSize);
1065	                if (result>=0) {
1066	                    if (result != static_cast<libzippp_int64>(maxSize)) {
1067	                        iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
1068	                    } else if (!writeFunc(data, maxSize)) {
1069	                        iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
1070	                    }
1071	                } else {
1072	                    iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
1073	                }
1074	                delete[] data;
1075	            } else {
1076	                iRes = LIBZIPPP_ERROR_MEMORY_ALLOCATION;
1077	            }
1078	        } else {
1079	            libzippp_uint64 uWrittenBytes = 0;
1080	            libzippp_int64 result = 0;
1081	            char* data = NEW_CHAR_ARRAY(chunksize)
1082	            if (data!=nullptr) {
1083	                string::size_type nbChunks = maxSize/chunksize;
1084	                for (libzippp_uint32 uiChunk=0 ; uiChunk<nbChunks ; ++uiChunk) {
1085	                    result = zip_fread(zipFile, data, chunksize);
1086	                    if (result>=0) {
1087	                        if (result!=static_cast<libzippp_int64>(chunksize)) {
1088	                            iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
1089	                            break;
1090	                        } else {
1091	                            if (!writeFunc(data, chunksize)) {
1092	                                iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
1093	                                break;
1094	                            }
1095	                            uWrittenBytes += result;
1096	                        }
1097	                    } else {
1098	                        iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
1099	                        break;
1100	                    }
1101	                }
