// Tests for state-consistent reading of entries while the archive is open in Write mode.
#include <cassert>
#include <cstring>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include "libzippp.h"

using namespace libzippp;
using namespace std;

static void createArchive(const string& path) {
    ZipArchive z(path);
    z.open(ZipArchive::New);
    z.addData("file.txt", "ORIGINAL-CONTENT", 17);
    z.addData("old.txt", "OLD-DATA", 8);
    z.addData("todelete.txt", "DELETE-ME", 9);
    z.close();
}

int main(void) {
    const string path = "state_test.zip";
    createArchive(path);

    // ---------------------------------------------------------------
    // 1) replace the same entry several times, read via a retained ZipEntry
    // ---------------------------------------------------------------
    {
        ZipArchive z(path);
        z.open(ZipArchive::Write);
        ZipEntry entry = z.getEntry("file.txt");
        assert(!entry.isNull());
        ZipEntry copy = entry; //object copies must behave the same

        //replace with LONGER content
        string longer = "REPLACED-CONTENT-THAT-IS-MUCH-LONGER-THAN-BEFORE";
        assert(z.addData("file.txt", longer.data(), longer.size()));
        assert(entry.readAsText(ZipArchive::Current)==longer);
        assert(copy.readAsText(ZipArchive::Current)==longer);
        assert(entry.readAsText(ZipArchive::Original)=="ORIGINAL-CONTENT");
        assert(copy.readAsText(ZipArchive::Original)=="ORIGINAL-CONTENT");

        //replace with SHORTER content
        assert(z.addData("file.txt", "SHORT", 5));
        assert(entry.readAsText(ZipArchive::Current)=="SHORT");
        assert(entry.readAsText(ZipArchive::Original)=="ORIGINAL-CONTENT");

        //replace with EMPTY content
        assert(z.addData("file.txt", "", 0));
        assert(entry.readAsText(ZipArchive::Current)=="");
        libzippp_uint8* nilOrEmpty = entry.readAsBinary(ZipArchive::Current);
        assert(nilOrEmpty!=nullptr); //empty content is a valid read
        delete[] nilOrEmpty;
        assert(entry.readAsText(ZipArchive::Original)=="ORIGINAL-CONTENT");

        //replace again with binary content containing zero bytes
        char binData[7] = {'A', '\0', 'B', '\0', '\0', 'C', 'D'};
        assert(z.addData("file.txt", binData, 7));
        //binary pointer read: full content, zero bytes preserved
        libzippp_uint8* raw = entry.readAsBinary(ZipArchive::Current);
        assert(raw!=nullptr);
        assert(memcmp(raw, binData, 7)==0);
        delete[] raw;
        //binary string read
