        char* asText = (char*)z.readEntry(entry, true, ZipArchive::Current);
        assert(asText!=nullptr);
        assert(memcmp(asText, binData, 7)==0);
        assert(asText[7]=='\0');
        delete[] asText;

        //size-limited reads: positive size = prefix of the selected state content
        string prefix = entry.readAsText(ZipArchive::Current, 3);
        assert(prefix.size()==3);
        assert(memcmp(prefix.data(), binData, 3)==0);
        //size beyond the actual length returns everything
        string all = entry.readAsText(ZipArchive::Current, 999);
        assert(all.size()==7);
        //size-limited read against the Original state
        string origPrefix = entry.readAsText(ZipArchive::Original, 4);
        assert(origPrefix=="ORIG");
        //zero size = full content
        assert(entry.readAsText(ZipArchive::Current, 0).size()==7);

        //chunked read (ostream) of the current content
        ostringstream oss;
        assert(z.readEntry(entry, oss, ZipArchive::Current, 2)==LIBZIPPP_OK);
        assert(oss.str().size()==7);
        assert(memcmp(oss.str().data(), binData, 7)==0);
        //chunked read via ZipEntry::readContent with default chunk size (0)
        ostringstream oss2;
        assert(entry.readContent(oss2, ZipArchive::Current, 0)==LIBZIPPP_OK);
        assert(oss2.str().size()==7);
        //chunked read of the original content
        ostringstream oss3;
        assert(z.readEntry(entry, oss3, ZipArchive::Original, 4)==LIBZIPPP_OK);
        assert(oss3.str()=="ORIGINAL-CONTENT");
        //chunked read via callback: complete and non-duplicated delivery
        string collected;
        int cbResult = z.readEntry(entry, [&collected](const void* data, libzippp_uint64 size) {
            collected.append((const char*)data, size);
            return true;
        }, ZipArchive::Current, 3);
        assert(cbResult==LIBZIPPP_OK);
        assert(collected.size()==7);
        assert(memcmp(collected.data(), binData, 7)==0);
        //callback returning false stops the output with the usual error
        int cbStop = z.readEntry(entry, [](const void*, libzippp_uint64) { return false; }, ZipArchive::Current, 3);
        assert(cbStop==LIBZIPPP_ERROR_OWRITE_FAILURE);

        //the retained object still exposes the name/size it was obtained with
        assert(entry.getName()=="file.txt");
        assert(entry.getSize()==17);

        //the pending changes are not committed by the reads
        z.discard();
    }
    {
        ZipArchive z(path);
        z.open(ZipArchive::ReadOnly);
        assert(z.getEntry("file.txt").readAsText()=="ORIGINAL-CONTENT");
        z.close();
    }

    // ---------------------------------------------------------------
    // 2) rename: state decides existence, name and size on lookups
    // ---------------------------------------------------------------
    {
        ZipArchive z(path);
        z.open(ZipArchive::Write);
        ZipEntry before = z.getEntry("old.txt");
        assert(z.renameEntry(before, "new.txt")==1);

        //Current: only new.txt exists
        assert(z.hasEntry("new.txt", false, true, ZipArchive::Current));
        assert(!z.hasEntry("old.txt", false, true, ZipArchive::Current));
        ZipEntry cur = z.getEntry("new.txt", false, true, ZipArchive::Current);
        assert(!cur.isNull());
        assert(cur.getName()=="new.txt");
        assert(cur.getSize()==8);
        assert(z.getEntry("old.txt", false, true, ZipArchive::Current).isNull());

        //Original: old.txt is still found with its original name and size
        assert(z.hasEntry("old.txt", false, true, ZipArchive::Original));
        assert(!z.hasEntry("new.txt", false, true, ZipArchive::Original));
        ZipEntry orig = z.getEntry("old.txt", false, true, ZipArchive::Original);
        assert(!orig.isNull());
        assert(orig.getName()=="old.txt");
        assert(orig.getSize()==8);
        assert(z.getEntry("new.txt", false, true, ZipArchive::Original).isNull());

        //getEntries reflects the state as well
        vector<ZipEntry> curEntries = z.getEntries(ZipArchive::Current);
        vector<ZipEntry> origEntries = z.getEntries(ZipArchive::Original);
        bool foundNew = false, foundOldInCur = false;
        for (vector<ZipEntry>::const_iterator it=curEntries.begin() ; it!=curEntries.end() ; ++it) {
            if (it->getName()=="new.txt") { foundNew = true; }
            if (it->getName()=="old.txt") { foundOldInCur = true; }
        }
        assert(foundNew && !foundOldInCur);
        bool foundOld = false;
        for (vector<ZipEntry>::const_iterator it=origEntries.begin() ; it!=origEntries.end() ; ++it) {
            if (it->getName()=="old.txt") { foundOld = true; }
        }
        assert(foundOld);

        //the retained object keeps its retrieval-time name but reads follow the explicit state
        assert(before.getName()=="old.txt");
        assert(before.readAsText(ZipArchive::Current)=="OLD-DATA");
        assert(before.readAsText(ZipArchive::Original)=="OLD-DATA");

