        char* byName = (char*)z.readEntry("new.txt", true, ZipArchive::Current);
        assert(byName!=nullptr);
        assert(string(byName)=="OLD-DATA");
        delete[] byName;
        assert(z.readEntry("new.txt", true, ZipArchive::Original)==nullptr);
        char* byNameOrig = (char*)z.readEntry("old.txt", true, ZipArchive::Original);
        assert(byNameOrig!=nullptr);
        assert(string(byNameOrig)=="OLD-DATA");
        delete[] byNameOrig;
        assert(z.readEntry("old.txt", true, ZipArchive::Current)==nullptr);

        z.discard();
    }

    // ---------------------------------------------------------------
    // 3) deletion and addition across states
    // ---------------------------------------------------------------
    {
        ZipArchive z(path);
        z.open(ZipArchive::Write);
        ZipEntry retained = z.getEntry("todelete.txt");
        assert(!retained.isNull());
