        assert(added.readAsText(ZipArchive::Current)=="FRESH");
        assert(added.readAsText(ZipArchive::Original)=="");
        assert(added.readAsBinary(ZipArchive::Original)==nullptr);
        assert(z.getEntry("added.txt", false, true, ZipArchive::Original).isNull());
        assert(!z.hasEntry("added.txt", false, true, ZipArchive::Original));
        assert(z.readEntry("added.txt", true, ZipArchive::Original)==nullptr);
        ostringstream ossAdd;
        assert(z.readEntry(added, ossAdd, ZipArchive::Original)==LIBZIPPP_ERROR_FOPEN_FAILURE);
        assert(ossAdd.str().empty());
        ostringstream ossAdd2;
        assert(z.readEntry(added, ossAdd2, ZipArchive::Current)==LIBZIPPP_OK);
        assert(ossAdd2.str()=="FRESH");

        //empty new file: chunked read succeeds
        assert(z.addData("empty.txt", "", 0));
        ZipEntry emptyEntry = z.getEntry("empty.txt");
        ostringstream ossEmpty;
        bool emptyDelivered = false;
        int emptyRes = z.readEntry(emptyEntry, [&emptyDelivered](const void*, libzippp_uint64) { emptyDelivered = true; return true; }, ZipArchive::Current, 16);
        assert(emptyRes==LIBZIPPP_OK);
        assert(z.readEntry(emptyEntry, ossEmpty, ZipArchive::Current)==LIBZIPPP_OK);
        assert(ossEmpty.str().empty());
        assert(emptyEntry.readAsText(ZipArchive::Current)=="");
        libzippp_uint8* emptyRaw = emptyEntry.readAsBinary(ZipArchive::Current);
        assert(emptyRaw!=nullptr);
        delete[] emptyRaw;

        z.discard();
    }

    // ---------------------------------------------------------------
    // 4) plain read-only archives are unaffected
    // ---------------------------------------------------------------
    {
        ZipArchive z(path);
        z.open(ZipArchive::ReadOnly);
        ZipEntry entry = z.getEntry("file.txt");
        assert(entry.readAsText()=="ORIGINAL-CONTENT");
        assert(entry.readAsText(ZipArchive::Original)=="ORIGINAL-CONTENT");
        assert(entry.readAsText(ZipArchive::Current, 4)=="ORIG");
        ostringstream oss;
        assert(z.readEntry(entry, oss)==LIBZIPPP_OK);
        assert(oss.str()=="ORIGINAL-CONTENT");
        char* byName = (char*)z.readEntry("old.txt", true);
        assert(byName!=nullptr && string(byName)=="OLD-DATA");
        delete[] byName;
        z.close();
    }

    remove(path.c_str());
    cout << "all state-consistency tests passed." << endl;
    return 0;
}

